import re
import time

public_msg_dict = {
    'Frame': 'frame',
    'Ethernet': 'eth',
    'Internet Protocol': 'ip',
    'Virtual LAN': 'vlan'}


class Wireshark_Msg_Handle(object):
    'class'

    def __init__(self):
        pass

    def _head_msg(self, line):
        'head'
        index_dict = {}
        index_dict['line_num'] = 0
        index_dict['content'] = line
        index_dict['indent'] = len(line) - len(line.strip())
        index_dict['value'] = None
        index_dict['parent'] = None
        key = line
        for pb_key in public_msg_dict.keys():
            if pb_key in line:
                key = public_msg_dict[pb_key]
                index_dict['key'] = key
                return index_dict

        specical_char = [',', '(', ]
        for char in specical_char:
            if char in line:
                key = line.split(char, 1)[0]
                break

        simple_key = ''
        if ' ' in key:
            for k in key:
                if k.isupper() or k.isdigit():
                    simple_key += k
        if simple_key:
            key = simple_key
        key = key.lower()
        index_dict['key'] = key

        return index_dict

    def parse_key_value(self, line):
        'key value'
        spcical_char = [',', ':', ]
        for i in range(len(line)):
            if line[i] in spcical_char:
                break
        key = line[:i]
        if '(' in key:
            key = key[:key.index('(')]
        value = line[i + 1:].strip()

        if '=' in key:
            key = key.split('=')[-1].strip()
        key = '_'.join([k.lower() for k in key.split()])

        if len(value) == 1 and value in ['{', '(']:
            value = None
        elif '(' and ')' in value and value.endswith(')'):
            value = value.split('(')[-1].strip(')')
        elif '[' and '[' in value and value.endswith(']'):
            value = value.split('[')[-1].strip(']')
        elif '<' and '>' in value and value.endswith('>'):
            value = value.split('<')[-1].strip('>')
        key = key.strip('[')
        value = value.strip(']')
        return key, value

    def msg_2_dict(self, data):
        'dict'
        if isinstance(data, list):
            lines = data
        else:
            lines = data.splitlines()
        lines = [x.rstrip() for x in lines]
        lines = [x for x in lines if x != '']
        index_dict = {}
        index_dict[0] = self._head_msg(lines[0])
        for i in range(1, len(lines)):
            index_dict[i] = {}
            index_dict[i]['content'] = lines[i]
            index_dict[i]['line_num'] = i
            line = lines[i].strip()
            index_dict[i]['indent'] = len(lines[i]) - len(lines[i].strip())
            for j in range(i, -1, -1):
                if index_dict[i]['indent'] - index_dict[j]['indent'] == 4:
                    index_dict[i]['parent'] = index_dict[j]['key']
                    break
            # protocolIEs: 4 items -> protocolIEs = 4 items
            if ':' in line or ',' in line:
                key, value = self.parse_key_value(line)
                index_dict[i]['key'] = key

                index_dict[i]['value'] = value
            elif ' ' not in line:
                index_dict[i]['key'] = line
                index_dict[i]['value'] = None
            elif ' ' in line:
                index_dict[i]['key'] = '_'.join(
                    [k.lower() for k in line.split()])
                index_dict[i]['value'] = None

            if 'parent' in index_dict[i].keys(
            ) and index_dict[i]['parent'] is not None:
                index_dict[i]['key'] = '%s.%s' % (
                    index_dict[i]['parent'], index_dict[i]['key'])

        check_msg = []

        for i in index_dict:
            if index_dict[i]['value'] is not None:
                # print('%s = %s' % (
                #    index_dict[i]['key'], index_dict[i]['value']))
                check_msg.append('%s = %s' % (index_dict[i]
                                              ['key'], index_dict[i]['value']))
                if 'frame.arrival_time' == index_dict[i]['key']:
                    check_msg.append('frame.arrival_time_s = %s' % self._time_to_s(index_dict[i]['value']))
        return check_msg

    def _time_to_s(self, timestamp):
        'Jan  6, 2013 16:04:28.289947000'

        ret = re.search(r'(.*\d\d:\d\d:\d\d).\d+', timestamp)
        frame_timestamp = ret.groups()[0]
        times = str(time.mktime(time.strptime(frame_timestamp, "%b %d, %Y %H:%M:%S"))).split('.')[0]

        return times

    def parse_single_msg(self, frame):
        'null'
        datas = []
        if isinstance(frame, list):
            tmp = frame
        else:
            tmp = frame.strip().splitlines()
        tmp = [x for x in tmp if x != '']
        for d in range(len(tmp)):
            if tmp[d].startswith('Frame'):
                start = d
            if d > start and not tmp[d].startswith(' '):
                datas.append(tmp[start:d])
                start = d
        datas.append(tmp[start:d])
        msg = []
        for d in datas:
            msg += self.msg_2_dict(d)
        ser = []
        for m in msg:
            ii = m.split('.')[0]
            if ii not in ser:
                ser.append(ii)
        index = '.'.join(ser)
        return [index] + msg

    def parse_file(self, file_path):
        'null'
        with open(file_path, 'r') as obj:
            lines = obj.read()
        frames_dict = {}

        frame_numbers = re.findall(r'Frame (\d+).*', lines)
        frame_numbers = [int(x) for x in frame_numbers]

        line_num = []
        lines = lines.splitlines()
        for i in range(len(lines)):
            if re.search(r'Frame (\d+)', lines[i]):
                line_num.append(i)
        for i in range(len(frame_numbers)):
            if i == len(frame_numbers) - 1:
                ret = self.parse_single_msg(lines[line_num[i]:])
            else:
                ret = self.parse_single_msg(
                    lines[line_num[i]:(line_num[i + 1] - 1)])
            frames_dict[frame_numbers[i]] = ret

        self.search_list = sorted(frames_dict)
        with open('%s_decode' % file_path, 'w') as obj:
            for i in sorted(frames_dict):
                msg = '\r\n'.join(frames_dict[i])
                obj.writelines("===================Msg: %s start================\r\n \
                               %s\r\n===================Msg: %s stop================\r\n\r\n" % (i, msg, i))

        return frames_dict
